4	static void expect_flip(Halfedge_Mesh &mesh, Halfedge_Mesh::EdgeRef edge, Halfedge_Mesh const &after) {
5		if (auto ret = mesh.flip_edge(edge)) {
6			if (auto msg = mesh.validate()) {
7				throw Test::error("Invalid mesh: " + msg.value().second);
8			}
9			// check if returned edge is the same edge
10			if (ret != edge) {
11				throw Test::error("Did not return the same edge!");
12			}
13			// check mesh shape:
14			if (auto difference = Test::differs(mesh, after, Test::CheckAllBits)) {
15				throw Test::error("Resulting mesh did not match expected: " + *difference);
16			}
17		} else {
18			throw Test::error("flip_edge rejected operation!");
19		}
20	}
