721	struct hash< std::pair< A, B > > {
722		size_t operator()(std::pair< A, B > const &key) const {
723			static const std::hash< A > ha;
724			static const std::hash< B > hb;
725			size_t hf = ha(key.first);
726			size_t hs = hb(key.second);
727			//NOTE: if this were C++20 we could use std::rotr or std::rotl
728			return hf ^ (hs << (sizeof(size_t)*4)) ^ (hs >> (sizeof(size_t)*4));
729		}
