388			return "Bone extents do not match!";
389		}
390		if (differs(a.roll, b.roll)) {
391			return "Bone rolls do not match!";
392		}
393		if (differs(a.radius, b.radius)) {
394			return "Bone radii do not match!";
395		}
396		if (differs(a.pose, b.pose)) {
397			return "Bone poses do not match!";
398		}
399		return std::nullopt;
400	}
