30	void Halfedge_Mesh::interpolate_data(std::vector< HalfedgeCRef > const &from, HalfedgeRef to) {
31		assert(from.size() >= 1);
32	
33		Vec2 uv_sum = Vec2(0.0f, 0.0f);
34		Vec3 normal_sum = Vec3(0.0f, 0.0f, 0.0f);
35	
36		for (HalfedgeCRef const h : from) {
37			uv_sum += h->corner_uv;
38			normal_sum += h->corner_normal;
39		}
40		to->corner_uv = uv_sum / float(from.size());
41		if (normal_sum == Vec3(0.0f, 0.0f, 0.0f)) {
42			to->corner_normal = Vec3(0.0f, 0.0f, 0.0f);
43		} else {
44			to->corner_normal = normal_sum.unit();
45		}
46	}
